    "weight": 0.0,
    "length": 0.0,
    "width": 0.0,
    "height": 0.0,
    "color": "string",
    "relative_size": "extra-small",
    "rating": 0.0,
    "num_product_reviews": 1,
    "num_product_questions": 1,
    "shareable_link": "string",
    "variations": [
     {
